const findString = (words: string[], s: string): number => {
  let lo = 0;
  let hi = words.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    let m = mid;
    while (m < hi && words[m] === '') m++;
    if (words[m] === '') {
      hi = mid - 1;
      continue;
    }
    if (words[m] === s) return m;
    if (words[m] < s) {
      lo = m + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
};
